
'use client';

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { MoreHorizontal, Search, Mail, Trash2 } from 'lucide-react';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { format, parseISO } from 'date-fns';
import { useToast } from '@/hooks/use-toast';
import { supabase } from '@/lib/supabase/client';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle, AlertDialogTrigger } from '@/components/ui/alert-dialog';
import { DropdownMenu, DropdownMenuTrigger, DropdownMenuContent, DropdownMenuLabel, DropdownMenuItem, DropdownMenuSeparator } from '@/components/ui/dropdown-menu';


// Define a structure for the contact message
interface ContactMessage {
  id: number;
  name: string | null;
  email: string | null;
  subject: string | null;
  message: string | null;
  created_at: string;
}

export default function ManageContactMessagesPage() {
  const [messages, setMessages] = useState<ContactMessage[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [messageToDelete, setMessageToDelete] = useState<ContactMessage | null>(null);
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
  const { toast } = useToast();

  const fetchMessages = React.useCallback(async () => {
      setLoading(true);
      try {
        const { data: fetchedMessages, error } = await supabase
            .from('contact_messages')
            .select('*')
            .order('created_at', { ascending: false });

        if (error) throw error;
        
        setMessages(fetchedMessages || []);
      } catch (error) {
           console.error("Failed to fetch messages from Supabase:", error);
           toast({
            title: "Error",
            description: "Failed to load messages from the database.",
            variant: "destructive",
        });
      } finally {
          setLoading(false);
      }
  }, [toast]);


  useEffect(() => {
    fetchMessages();
  }, [fetchMessages]);

  const openDeleteDialog = (message: ContactMessage) => {
    setMessageToDelete(message);
    setIsDeleteDialogOpen(true);
  };
  
  const handleDeleteMessage = async () => {
    if (!messageToDelete) return;
    try {
        const { error } = await supabase
            .from('contact_messages')
            .delete()
            .eq('id', messageToDelete.id);
        
        if (error) throw error;

        setMessages(prev => prev.filter(msg => msg.id !== messageToDelete.id));
        toast({
            title: "Message Deleted",
            description: `The message from ${messageToDelete.name} has been deleted.`,
        });

    } catch (error) {
        console.error("Error deleting message:", error);
        toast({
            title: 'Error',
            description: 'Could not delete the message from the database.',
            variant: 'destructive',
        });
    } finally {
        setIsDeleteDialogOpen(false);
        setMessageToDelete(null);
    }
  }


  const filteredMessages = messages.filter(message =>
    (message.name || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
    (message.email || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
    (message.subject || '').toLowerCase().includes(searchTerm.toLowerCase())
  );


  return (
    <div className="space-y-8">
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Mail className="h-6 w-6 text-primary" />
              <div>
                <CardTitle>Contact Messages</CardTitle>
                <CardDescription>View and manage messages submitted through the contact form.</CardDescription>
              </div>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-between gap-4 mb-6">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input 
                placeholder="Search by name, email, or subject..." 
                className="pl-10" 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
          </div>
          
          <div className="border rounded-md">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>From</TableHead>
                  <TableHead>Subject</TableHead>
                  <TableHead>Date Received</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {loading ? (
                    <TableRow>
                        <TableCell colSpan={4} className="h-24 text-center">
                            Loading messages from database...
                        </TableCell>
                    </TableRow>
                ) : filteredMessages.length > 0 ? (
                    filteredMessages.map((message) => (
                    <TableRow key={message.id}>
                        <TableCell className="font-medium">
                            <div className="flex flex-col">
                                <span>{message.name || 'N/A'}</span>
                                <span className="text-xs text-muted-foreground">{message.email || 'No email'}</span>
                            </div>
                        </TableCell>
                        <TableCell>{message.subject || 'No Subject'}</TableCell>
                        <TableCell>{message.created_at ? format(parseISO(message.created_at), 'dd MMM, yyyy') : 'N/A'}</TableCell>
                        <TableCell className="text-right">
                        <AlertDialog>
                            <DropdownMenu>
                                <DropdownMenuTrigger asChild>
                                <Button variant="ghost" className="h-8 w-8 p-0">
                                    <span className="sr-only">Open menu</span>
                                    <MoreHorizontal className="h-4 w-4" />
                                </Button>
                                </DropdownMenuTrigger>
                                <DropdownMenuContent align="end">
                                    <DropdownMenuLabel>Actions</DropdownMenuLabel>
                                    <AlertDialogTrigger asChild>
                                        <DropdownMenuItem>
                                        View Message
                                        </DropdownMenuItem>
                                    </AlertDialogTrigger>
                                    <DropdownMenuSeparator />
                                    <DropdownMenuItem onClick={() => openDeleteDialog(message)} className="text-destructive">
                                        <Trash2 className="mr-2 h-4 w-4" /> Delete
                                    </DropdownMenuItem>
                                </DropdownMenuContent>
                            </DropdownMenu>

                            <AlertDialogContent>
                                <AlertDialogHeader>
                                <AlertDialogTitle>Message from {message.name}</AlertDialogTitle>
                                <AlertDialogDescription className="pt-2">
                                    <p><strong>Email:</strong> {message.email}</p>
                                    <p><strong>Subject:</strong> {message.subject}</p>
                                    <p className="mt-4 text-foreground whitespace-pre-wrap">{message.message}</p>
                                </AlertDialogDescription>
                                </AlertDialogHeader>
                                <AlertDialogFooter>
                                <AlertDialogCancel>Close</AlertDialogCancel>
                                </AlertDialogFooter>
                            </AlertDialogContent>
                        </AlertDialog>
                        </TableCell>
                    </TableRow>
                    ))
                ) : (
                     <TableRow>
                        <TableCell colSpan={4} className="h-24 text-center">
                            No messages found.
                        </TableCell>
                    </TableRow>
                )}
              </TableBody>
            </Table>
          </div>
        </CardContent>
      </Card>
      
       <AlertDialog open={isDeleteDialogOpen} onOpenChange={setIsDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Are you absolutely sure?</AlertDialogTitle>
            <AlertDialogDescription>
              This action cannot be undone. This will permanently delete the message from <span className="font-semibold">{messageToDelete?.name}</span>.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDeleteMessage} className={buttonVariants({ variant: "destructive" })}>Delete Message</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

    </div>
  );
}

const buttonVariants = (props: { variant: "destructive" }) => "bg-destructive text-destructive-foreground hover:bg-destructive/90";

